effect.shader:
void main() {
    vec2 uv = acScreenNorm;
    vec2 d = uv - center;

    int N = int(samples);
    vec4 acc = vec4(0.0);
    for (int i = 0; i < 48; i++) {
        if (i >= N) break;
        float t = float(i) / float(N - 1);
        float s = mix(1.0, 1.0 - amount, t);
        acc += texture(inputImg, center + d * s);
    }
    fragColor = acc / float(N);
}
